/// <summary>
/// Lookup on control NDXLengthUnitOfMeasure event handler 
/// </summary>
/// <param name = "sender">Control</param>
/// <param name = "e">Eventargs</param>
[FormControlEventHandler(formControlStr(UnitOfMeasureConversionEditOrCreate, NDXDimensions_NDXLengthUnitOfMeasure), FormControlEventType::Lookup)]
public static void NDXDimensions_NDXLengthUnitOfMeasure_OnLookup(FormControl sender, FormControlEventArgs e)
{
    FormControlCancelableSuperEventArgs ce = e as FormControlCancelableSuperEventArgs;
    UnitOfMeasureLookup::lookupReferenceForUnitOfMeasureClass(sender, UnitOfMeasureClass::Length);

    if(ce)
    {
        ce.CancelSuperCall();
    }
}

/// <summary>
